  deleted_count integer := 0;
BEGIN
  DELETE FROM public.push_tokens
  WHERE created_at < NOW() - (p_max_age_days || ' days')::interval;

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_gratitude_entry_by_date(p_entry_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_deleted_count INTEGER;
BEGIN
  -- Get authenticated user ID
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'User not authenticated';
  END IF;

  -- Validate date format and reasonable bounds
  IF p_entry_date IS NULL THEN
    RAISE EXCEPTION 'Entry date cannot be null';
  END IF;

  -- Delete the entire entry atomically
  DELETE FROM gratitude_entries
  WHERE user_id = v_user_id AND entry_date = p_entry_date;

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  -- Update user streak after deletion (important for streak accuracy)
  PERFORM update_user_streak(v_user_id);

  -- Log the operation for debugging (optional)
  -- Could be removed in production for performance
  IF v_deleted_count > 0 THEN
    -- Entry was successfully deleted
    NULL; -- Placeholder for potential logging
  ELSE
    -- No entry found for the given date (not an error, just info)
    NULL; -- Could log this if needed
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_gratitude_statement(p_entry_date date, p_statement_index integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_row_id uuid;
  v_statements jsonb;
  v_moods jsonb;
  v_len int;
  v_new_statements jsonb;
  v_new_moods jsonb;
begin
  if v_user_id is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select id, coalesce(statements, '[]'::jsonb), coalesce(moods, '{}'::jsonb)
    into v_row_id, v_statements, v_moods
  from public.gratitude_entries
  where user_id = v_user_id and entry_date = p_entry_date
  for update;

  if not found then
    raise exception 'Entry not found for date %', p_entry_date using errcode = 'P0002';
  end if;

  v_len := coalesce(jsonb_array_length(v_statements), 0);
  if p_statement_index < 0 or p_statement_index >= v_len then
    raise exception 'Invalid statement index %, length %', p_statement_index, v_len using errcode = '22003';
  end if;

  -- Remove the statement at the index and rebuild array
  select coalesce(jsonb_agg(elem.value order by elem.idx), '[]'::jsonb)
    into v_new_statements
  from (
    select value, idx
    from jsonb_array_elements(v_statements) with ordinality as e(value, idx)
    where (idx - 1) <> p_statement_index
  ) as elem;

  -- Shift/realign moods keys: remove the index, and decrement keys > index by 1
  select coalesce(
    jsonb_object_agg(
      case when (key)::int > p_statement_index then ((key)::int - 1)::text else key end,
      value
    ), '{}'::jsonb)
    into v_new_moods
  from (
    select key, value
    from jsonb_each(v_moods)
    where key <> (p_statement_index)::text
  ) as kv;

  if jsonb_array_length(v_new_statements) = 0 then
    -- Delete the entire row when no statements remain
    delete from public.gratitude_entries where id = v_row_id;
  else
    update public.gratitude_entries
    set statements = v_new_statements,
        moods = v_new_moods,
        updated_at = now()
    where id = v_row_id;
  end if;
end;
$function$

