CREATE OR REPLACE FUNCTION public.update_user_streak()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
   DECLARE
       v_user_id UUID;
       v_calculated_current_streak_for_block INT := 0;
       v_final_current_streak_to_set INT := 0;
       v_longest_streak_from_calculation INT := 0;
       v_loop_last_processed_date DATE;
       v_streak_block_end_date DATE;
       entry_record RECORD;
   BEGIN
       IF (TG_OP = 'DELETE') THEN
           v_user_id := OLD.user_id;
       ELSE
           v_user_id := NEW.user_id;
       END IF;

       FOR entry_record IN
           SELECT entry_date
           FROM public.gratitude_entries
           WHERE user_id = v_user_id
           ORDER BY entry_date ASC
       LOOP
           IF v_loop_last_processed_date IS NULL THEN
               v_calculated_current_streak_for_block := 1;
           ELSE
               IF entry_record.entry_date = v_loop_last_processed_date + INTERVAL '1 day' THEN
                   v_calculated_current_streak_for_block := v_calculated_current_streak_for_block + 1;
               ELSE
                   v_calculated_current_streak_for_block := 1;
               END IF;
           END IF;

           IF v_calculated_current_streak_for_block > v_longest_streak_from_calculation THEN
               v_longest_streak_from_calculation := v_calculated_current_streak_for_block;
           END IF;

           v_loop_last_processed_date := entry_record.entry_date;
           v_streak_block_end_date := entry_record.entry_date;
       END LOOP;

       IF v_loop_last_processed_date IS NULL THEN
           v_final_current_streak_to_set := 0;
           v_longest_streak_from_calculation := 0;
           v_streak_block_end_date := NULL;
       ELSE
           IF v_streak_block_end_date = CURRENT_DATE
              OR v_streak_block_end_date = (CURRENT_DATE - INTERVAL '1 day') THEN
               v_final_current_streak_to_set := v_calculated_current_streak_for_block;
           ELSE
               v_final_current_streak_to_set := 0;
           END IF;
       END IF;

       INSERT INTO public.streaks (
           user_id, current_streak, longest_streak, last_entry_date, updated_at
       )
       VALUES (
           v_user_id, v_final_current_streak_to_set, v_longest_streak_from_calculation, v_streak_block_end_date, now()
       )
       ON CONFLICT (user_id) DO UPDATE
       SET current_streak = EXCLUDED.current_streak,
           longest_streak = GREATEST(public.streaks.longest_streak, EXCLUDED.longest_streak),
           last_entry_date = EXCLUDED.last_entry_date,
           updated_at = now();

       RETURN NULL;
   END;
$function$
